            const mat = new MeshBasicMaterial({ color, wireframe: true, transparent: true, opacity: 0.25 });
            const m = new Mesh(geo, mat);
            m.position.set(gc * CELL + CELL / 2, gr * CELL + CELL / 2, 0);
