  // ─── ACHIEVEMENT CHECK ────────────────────────────────────────
  function checkAchievement(id: string) {
    if (save.achievements.includes(id)) return;
    save.achievements.push(id);
    writeSave(save);
    const ach = ACHIEVEMENTS.find(a => a.id === id);
    if (ach) {
      showToast(`${ach.name}: ${ach.desc}`);
      audio.achievement();
